package com.smartwater;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.smartwater.Store.*;
@Service
public class BusinessQueries {
 final Store db; public BusinessQueries(Store db){this.db=db;}
 public List<Map<String,Object>> devices(){return db.rows("SELECT * FROM device ORDER BY id").stream().map(this::device).toList();}
 Map<String,Object> device(Map<String,Object> row){String id=row.get("id").toString();var metrics=db.rows("SELECT * FROM metric_definition WHERE device_id=? ORDER BY key",id);return map("id",id,"unit_id",row.get("unit_id"),"name",row.get("name"),"description",row.get("description"),"modelStatus","MODELLED","metrics",metrics.stream().map(m->m.get("key")).toList(),"metricDefinitions",metrics,"asset_root_node",row.get("asset_root_node"),"mechanical_node",row.get("mechanical_node"),"available_metrics",metrics.stream().map(m->m.get("key")).toList(),"operating_state","NOT_OBSERVED","limitation","已建模和无告警均不代表设备健康；数据来源为独立模拟采集器");}
 Map<String,Object> descriptor(String id){try{return db.one("SELECT * FROM data_snapshot WHERE id=?",UUID.fromString(id));}catch(IllegalArgumentException e){throw ApiFailure.bad("INVALID_SNAPSHOT","快照标识无效");}}
 @Transactional(isolation=Isolation.REPEATABLE_READ)
 public Map<String,Object> dashboard(String actor){
  var state=db.one("SELECT * FROM dataset_state WHERE id=1");UUID id=UUID.randomUUID();Instant at=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS);db.jdbc.update("INSERT INTO data_snapshot(id,revision,as_of,scenario,created_by,created_at,context) VALUES(?,?,?,?,?,?,?::jsonb)",id,state.get("revision"),at.atOffset(ZoneOffset.UTC),state.get("scenario"),actor,OffsetDateTime.now(ZoneOffset.UTC),db.encode(map("devices",devices(),"rules",rules())));return snapshot(id.toString());
 }
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Map<String,Object> snapshot(String id){
  var view=descriptor(id);Instant at=instant(view.get("as_of"));var readings=new LinkedHashMap<String,Object>();var history=new LinkedHashMap<String,Object>();
  for(var definition:catalog(view).stream().flatMap(d->definitions(d).stream()).toList()){String device=definition.get("device_id").toString(),key=definition.get("key").toString();readings.put(key,latest(view,definition));if(List.of("do","blower_power").contains(key))history.put(key,series(view,device,key,24));}
  return map("snapshotId",id,"version","smartwater-business-v02","scenario",view.get("scenario"),"tick",view.get("revision"),"demoTime",at.toString(),"updatedAt",at.toString(),"readings",readings,"history",history,"alarms",alarms(id,null,true),"backend",map("snapshotId",id,"revision",view.get("revision"),"dataMode","BUSINESS_API","source","SIMULATED","devices",catalog(view),"rules",context(view).get("rules")));
 }
 private Map<String,Object> context(Map<String,Object> view){var frozen=db.decode(view.get("context"));return frozen.isEmpty()?map("devices",devices(),"rules",rules()):frozen;}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> catalog(Map<String,Object> view){return (List<Map<String,Object>>)context(view).get("devices");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> definitions(Map<String,Object> device){return (List<Map<String,Object>>)device.get("metricDefinitions");}
 public Map<String,Object> details(String snapshot,String id){return catalog(descriptor(snapshot)).stream().filter(d->d.get("id").equals(id)).findFirst().orElseThrow(()->new ApiFailure(404,"DEVICE_NOT_FOUND","设备不在指定业务快照中"));}
 private Map<String,Object> rules(){var rule=db.one("SELECT * FROM alarm_rule WHERE id='DEMO_DO_LOW'");return map("lowDo",map("id",rule.get("id"),"below",rule.get("threshold"),"unit","mg/L","label",rule.get("label"),"version",rule.get("version")));}
 private Map<String,Object> latest(Map<String,Object> view,Map<String,Object> definition){String device=definition.get("device_id").toString(),key=definition.get("key").toString();var rows=db.rows("SELECT * FROM telemetry WHERE device_id=? AND metric_key=? AND revision<=? AND observed_at<=? ORDER BY observed_at DESC,revision DESC LIMIT 1",device,key,view.get("revision"),view.get("as_of"));if(rows.isEmpty())return map("scopeType","DEVICE","scopeId",device,"metricKey",key,"value",null,"unit",definition.get("unit"),"observedAt",iso(view.get("as_of")),"sampleAt",iso(view.get("as_of")),"quality","MISSING","rawQuality","MISSING","source","SIMULATED","snapshotId",view.get("id").toString(),"recordId",null);
  var result=reading(rows.get(0),view);if(result.get("quality").equals("GOOD")&&Duration.between(instant(rows.get(0).get("observed_at")),instant(view.get("as_of"))).getSeconds()>((Number)definition.get("stale_seconds")).intValue())result.put("quality","STALE");return result;
 }
 private Map<String,Object> reading(Map<String,Object> row,Map<String,Object> view){return map("scopeType","DEVICE","scopeId",row.get("device_id"),"metricKey",row.get("metric_key"),"value",row.get("value"),"unit",row.get("unit"),"observedAt",iso(row.get("observed_at")),"sampleAt",iso(row.get("observed_at")),"quality",row.get("quality"),"rawQuality",row.get("quality"),"source",row.get("source"),"snapshotId",view.get("id").toString(),"recordId",row.get("id").toString());}
 private List<Map<String,Object>> series(Map<String,Object> view,String device,String key,int hours){Instant end=instant(view.get("as_of")),start=end.minusSeconds(hours*3600L);return db.rows("SELECT * FROM (SELECT DISTINCT ON (date_trunc('minute',observed_at)) * FROM telemetry WHERE device_id=? AND metric_key=? AND revision<=? AND observed_at>=? AND observed_at<=? ORDER BY date_trunc('minute',observed_at),observed_at DESC,revision DESC) sample ORDER BY observed_at LIMIT 1441",device,key,view.get("revision"),start.atOffset(ZoneOffset.UTC),end.atOffset(ZoneOffset.UTC)).stream().map(row->reading(row,view)).toList();}
 @Transactional(readOnly=true)
 public Map<String,Object> metrics(String snapshot,String device,List<String> requested,Integer hours){
  if(hours!=null&&!List.of(1,6,24).contains(hours))throw ApiFailure.bad("INVALID_TIME_RANGE","仅支持 1h / 6h / 24h");var view=descriptor(snapshot);var entity=details(snapshot,device);var definitions=definitions(entity);List<String> available=definitions.stream().map(m->m.get("key").toString()).toList();if(requested!=null&&(requested.isEmpty()||requested.size()>4||new HashSet<>(requested).size()!=requested.size()))throw ApiFailure.bad("EMPTY_METRIC_KEYS","指标列表须为 1–4 个不重复项；无指标设备请省略 metricKeys，返回 NO_DEFINED_METRICS");if(requested!=null&&!available.containsAll(requested))throw ApiFailure.bad("METRIC_NOT_OWNED","指定指标不属于该设备");var keys=requested==null?available:requested;var result=new ArrayList<Map<String,Object>>();for(String key:keys){var def=definitions.stream().filter(d->d.get("key").equals(key)).findFirst().orElseThrow();if(hours!=null&&!List.of("do","blower_power").contains(key))throw ApiFailure.bad("HISTORY_NOT_AVAILABLE","当前仅 DO / 功率支持趋势，请省略其他指标的 hours");result.add(map("metric_key",key,"label",def.get("label"),"unit",def.get("unit"),"latest",latest(view,def),"history",hours==null?null:statistics(view,device,key,hours)));}return map("outcome",available.isEmpty()?"NO_DEFINED_METRICS":"DATA_AVAILABLE","device_name",entity.get("name"),"metrics",result,"source","SIMULATED");
 }
 private Map<String,Object> statistics(Map<String,Object> view,String device,String key,int hours){Instant end=instant(view.get("as_of")),start=end.minusSeconds(hours*3600L);var row=db.one("SELECT count(*) total,count(*) FILTER(WHERE quality='GOOD') valid,count(*) FILTER(WHERE quality='MISSING') missing,count(*) FILTER(WHERE quality='STALE') stale,min(value) FILTER(WHERE quality='GOOD') minimum,max(value) FILTER(WHERE quality='GOOD') maximum,avg(value) FILTER(WHERE quality='GOOD') mean,min(observed_at) first_sample,max(observed_at) last_sample FROM (SELECT DISTINCT ON (date_trunc('minute',observed_at)) * FROM telemetry WHERE device_id=? AND metric_key=? AND revision<=? AND observed_at>=? AND observed_at<=? ORDER BY date_trunc('minute',observed_at),observed_at DESC,revision DESC) points",device,key,view.get("revision"),start.atOffset(ZoneOffset.UTC),end.atOffset(ZoneOffset.UTC));int expected=hours*60+1;return map("hours",hours,"total_samples",row.get("total"),"valid_samples",row.get("valid"),"missing_samples",row.get("missing"),"stale_samples",row.get("stale"),"invalid_samples",0,"expected_samples",expected,"unreported_samples",Math.max(0,expected-((Number)row.get("total")).intValue()),"coverage",((Number)row.get("valid")).doubleValue()/expected,"min",row.get("minimum"),"max",row.get("maximum"),"mean",row.get("mean"),"start",start.toString(),"end",end.toString(),"sample_start",iso(row.get("first_sample")),"sample_end",iso(row.get("last_sample")),"cadence_ms",60000,"window_semantics","start/end为请求时窗，sample_start/sample_end为实际覆盖；按分钟取最后一条样本");}
 @Transactional(readOnly=true)
 public List<Map<String,Object>> alarms(String snapshot,String device,boolean activeOnly){var view=descriptor(snapshot);return db.rows("SELECT DISTINCT ON(alarm_id) payload FROM alarm_event WHERE revision<=? ORDER BY alarm_id,revision DESC,id DESC",view.get("revision")).stream().map(row->db.decode(row.get("payload"))).filter(a->(device==null||device.equals(a.get("deviceId")))&&(!activeOnly||a.get("lifecycleStatus").equals("ACTIVE"))).sorted(Comparator.comparing(a->a.get("occurredAt").toString())).map(a->{a.put("snapshotId",snapshot);return a;}).toList();}
 @Transactional(readOnly=true)
 public Map<String,Object> inspect(String snapshot,String id){var view=descriptor(snapshot);var alarm=alarms(snapshot,null,false).stream().filter(a->a.get("alarmId").equals(id)).findFirst().orElseThrow(()->new ApiFailure(404,"ALARM_NOT_FOUND","告警不在指定快照中"));var definition=definitions(details(snapshot,alarm.get("deviceId").toString())).stream().filter(d->d.get("key").equals(alarm.get("metricKey"))).findFirst().orElseThrow();var current=latest(view,definition);return map("alarm",alarm,"metric_key",alarm.get("metricKey"),"unit",definition.get("unit"),"threshold",alarm.get("threshold"),"operator","<","rule_id",alarm.get("ruleId"),"rule_label",alarm.get("rule"),"rule_version",alarm.get("ruleVersion"),"trigger_comparison",((Number)alarm.get("valueAtEvent")).doubleValue()<((Number)alarm.get("threshold")).doubleValue(),"event_quality",alarm.get("eventQuality"),"event_quality_basis","PERSISTED_TRIGGER_READING","current_quality",current.get("quality"),"current_value",current.get("value"),"limitation","演示阈值，仅解释记录依据，不是设备故障因果或控制建议");}
 @Transactional
 public Map<String,Object> envelope(String snapshot,String tool,String device,Object data){var view=descriptor(snapshot);String id="EV_DB_"+UUID.randomUUID().toString().replace("-","");var result=map("evidence_id",id,"snapshot_id",snapshot,"as_of",iso(view.get("as_of")),"source","SIMULATED","tool_name",tool,"device_id",device,"data",data);db.jdbc.update("INSERT INTO query_evidence VALUES(?,?,?,?,?::jsonb,?)",id,UUID.fromString(snapshot),tool,device,db.encode(result),OffsetDateTime.now(ZoneOffset.UTC));return result;}
}
